import json, time, re
import runtime_checks as q
checks=[]
t=q.dump("final-management-queue")
assert "reads=0 summaries=1 progress=0" in q.labels(t)
q.tap(t,"下載內容管理")
t=q.dump("final-management-content")
assert "reads=1 summaries=1 progress=0" in q.labels(t),q.labels(t)
q.tap(t,"QA large book")
t=q.dump("final-management-expanded")
assert any("QA page" in x for x in q.labels(t))
q.tap(t,"PROGRESS")
time.sleep(3)
t=q.dump("final-management-progress")
assert "reads=1 summaries=1 progress=100" in q.labels(t),q.labels(t)
assert any("QA page" in x for x in q.labels(t))
checks.append("5000-page expansion survives 100 progress updates with one inventory read")
q.tap(t,"REMOVE")
t=q.dump("final-management-remove")
assert any("reads=2 " in x for x in q.labels(t)),q.labels(t)
checks.append("removal reloads once")
q.tap(t,"ERROR")
t=q.dump("final-management-error")
assert any("QA storage failure" in x for x in q.labels(t)),q.labels(t)
q.tap(t,"Reload")
t=q.dump("final-management-retry")
assert "reads=4 summaries=1 progress=100" in q.labels(t),q.labels(t)
checks.append("error and retry recover content")
q.screenshot("final-management-retry")
# Derive one scroll from the current root bounds.
node=next(t.iter("node"))
x1,y1,x2,y2=map(int,re.findall(r"\d+",node.get("bounds")))
q.adb("shell","input","swipe",str((x1+x2)//2),str(y1+(y2-y1)*4//5),str((x1+x2)//2),str(y1+(y2-y1)*2//5),"500")
t=q.dump("final-management-scroll")
q.screenshot("final-management-scroll")
assert any("QA page" in x for x in q.labels(t)),q.labels(t)
checks.append("expanded content scrolls")
q.ROOT.joinpath("final-management-checks.json").write_text(json.dumps(checks,indent=2))
print(json.dumps(checks))
